RACE_X["race-a28"]=Object.assign(RACE_X["race-a28"]||{},{cs:["using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        int[] a = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int[] kq = new int[n];\n        for (int i = 0; i < n; i++)\n        {\n            kq[i] = -1;\n            for (int j = i + 1; j < n; j++)\n            {\n                if (a[j] > a[i]) { kq[i] = a[j]; break; }\n            }\n        }\n        Console.WriteLine(string.Join(\" \", kq));\n    }\n}", "using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        int[] a = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int[] kq = new int[n];\n        Stack<int> st = new Stack<int>();     // chỉ số các phần tử chưa tìm thấy số lớn hơn\n        for (int i = 0; i < n; i++)\n        {\n            kq[i] = -1;\n            while (st.Count > 0 && a[st.Peek()] < a[i]) kq[st.Pop()] = a[i];\n            st.Push(i);\n        }\n        Console.WriteLine(string.Join(\" \", kq));\n    }\n}"]});
RACE_X["race-a28"]=Object.assign(RACE_X["race-a28"]||{},{py:["n = int(input())\na = list(map(int, input().split()))\nkq = [-1] * n\nfor i in range(n):\n    for j in range(i + 1, n):\n        if a[j] > a[i]:\n            kq[i] = a[j]\n            break\nprint(*kq)", "n = int(input())\na = list(map(int, input().split()))\nkq = [-1] * n\nst = []          # chỉ số các phần tử chưa tìm thấy số lớn hơn\nfor i in range(n):\n    while st and a[st[-1]] < a[i]:\n        kq[st.pop()] = a[i]\n    st.append(i)\nprint(*kq)"]});
makeStepRace(document.getElementById("race-a28"),{variants:[{label:"Nhìn sang phải từng ô: O(n²)",code:"#include <iostream>\nusing namespace std;\n\nint a[100000], kq[100000];\n\nint main() {\n    int n;\n    cin >> n;\n    for (int i = 0; i < n; i++) cin >> a[i];\n    for (int i = 0; i < n; i++) {\n        kq[i] = -1;\n        for (int j = i + 1; j < n; j++) {\n            if (a[j] > a[i]) { kq[i] = a[j]; break; }\n        }\n    }\n    for (int i = 0; i < n; i++) cout << kq[i] << \" \";\n    cout << \"\\n\";\n    return 0;\n}"},{label:"Ngăn xếp đơn điệu: O(n)",code:"#include <iostream>\n#include <stack>\nusing namespace std;\n\nint a[100000], kq[100000];\n\nint main() {\n    int n;\n    cin >> n;\n    for (int i = 0; i < n; i++) cin >> a[i];\n    stack<int> st;          // ch\u1ec9 s\u1ed1 c\u00e1c ph\u1ea7n t\u1eed ch\u01b0a t\u00ecm th\u1ea5y s\u1ed1 l\u1edbn h\u01a1n\n    for (int i = 0; i < n; i++) {\n        kq[i] = -1;\n        while (!st.empty() && a[st.top()] < a[i]) {\n            kq[st.top()] = a[i];\n            st.pop();\n        }\n        st.push(i);\n    }\n    for (int i = 0; i < n; i++) cout << kq[i] << \" \";\n    cout << \"\\n\";\n    return 0;\n}"}],gen:n=>n+"\n"+Array.from({length:n},(_,i)=>n-i).join(" "),ns:[50,100,200,400],note:"Dãy giảm dần là trường hợp xấu nhất của cách nhìn sang phải: không ô nào tìm thấy số lớn hơn nên phải nhìn tới cuối. Ngăn xếp đơn điệu vẫn chỉ đẩy vào, lấy ra mỗi chỉ số một lần."});
const PR28=[{label:"Ví dụ: Phần tử lớn hơn tiếp theo",input:"",code:"#include <iostream>\n#include <stack>\nusing namespace std;\n\nint a[8] = {4, 2, 1, 5, 3, 2, 6, 1};\nint kq[8];\n\nint main() {\n    int n = 8;\n    stack<int> st;          // chỉ số các phần tử chưa tìm thấy số lớn hơn\n    for (int i = 0; i < n; i++) {\n        kq[i] = -1;\n        while (!st.empty() && a[st.top()] < a[i]) {\n            kq[st.top()] = a[i];    // a[i] là số lớn hơn đầu tiên của đỉnh\n            st.pop();\n        }\n        st.push(i);\n    }\n    for (int i = 0; i < n; i++) cout << kq[i] << \" \";\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"bars",of:"a",ptr:["i"]},{type:"cont",of:"st",label:"st (chỉ số)"},{type:"cells",of:"kq"}],py:{code:"a = [4, 2, 1, 5, 3, 2, 6, 1]\nn = len(a)\nkq = [-1] * n\nst = []          # chỉ số các phần tử chưa tìm thấy số lớn hơn\nfor i in range(n):\n    while st and a[st[-1]] < a[i]:\n        kq[st.pop()] = a[i]     # a[i] là số lớn hơn đầu tiên của đỉnh\n    st.append(i)\nprint(*kq)",viz:[{type:"bars",of:"a",ptr:["i"]},{type:"cont",of:"st",as:"stack",label:"st (chỉ số)"},{type:"cells",of:"kq"}]},cs:{code:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] a = { 4, 2, 1, 5, 3, 2, 6, 1 };\n        int n = a.Length;\n        int[] kq = new int[n];\n        Stack<int> st = new Stack<int>();     // chỉ số các phần tử chưa tìm thấy số lớn hơn\n        for (int i = 0; i < n; i++)\n        {\n            kq[i] = -1;\n            while (st.Count > 0 && a[st.Peek()] < a[i])\n            {\n                kq[st.Pop()] = a[i];    // a[i] là số lớn hơn đầu tiên của đỉnh\n            }\n            st.Push(i);\n        }\n        Console.WriteLine(string.Join(\" \", kq));\n    }\n}",viz:[{type:"bars",of:"a",ptr:["i"]},{type:"cont",of:"st",as:"stack",label:"st (chỉ số)"},{type:"cells",of:"kq"}]}},{label:"Ví dụ: Số nhỏ hơn gần nhất bên trái",input:"",code:"#include <iostream>\n#include <stack>\nusing namespace std;\n\nint a[7] = {3, 7, 8, 4, 2, 6, 5};\n\nint main() {\n    int n = 7;\n    stack<int> st;          // các giá trị tăng dần từ đáy lên đỉnh\n    for (int i = 0; i < n; i++) {\n        while (!st.empty() && st.top() >= a[i]) st.pop();\n        cout << (st.empty() ? -1 : st.top()) << \" \";   // đỉnh còn lại là đáp án\n        st.push(a[i]);\n    }\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"bars",of:"a",ptr:["i"]},{type:"cont",of:"st"}],py:{code:"a = [3, 7, 8, 4, 2, 6, 5]\nst = []          # các giá trị tăng dần từ đáy lên đỉnh\nout = []\nfor i in range(len(a)):\n    while st and st[-1] >= a[i]:\n        st.pop()\n    out.append(st[-1] if st else -1)   # đỉnh còn lại là đáp án\n    st.append(a[i])\nprint(*out)",viz:[{type:"bars",of:"a",ptr:["i"]},{type:"cont",of:"st",as:"stack"}]},cs:{code:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] a = { 3, 7, 8, 4, 2, 6, 5 };\n        Stack<int> st = new Stack<int>();     // các giá trị tăng dần từ đáy lên đỉnh\n        for (int i = 0; i < a.Length; i++)\n        {\n            while (st.Count > 0 && st.Peek() >= a[i]) st.Pop();\n            Console.Write((st.Count == 0 ? -1 : st.Peek()) + \" \");   // đỉnh còn lại là đáp án\n            st.Push(a[i]);\n        }\n        Console.WriteLine();\n    }\n}",viz:[{type:"bars",of:"a",ptr:["i"]},{type:"cont",of:"st",as:"stack"}]}},{label:"Ví dụ: Hình chữ nhật lớn nhất trong biểu đồ cột",input:"",code:"#include <iostream>\n#include <stack>\nusing namespace std;\n\nint h[6] = {2, 1, 5, 6, 2, 3};\nint Lt[6], Rt[6];   // chỉ số cột thấp hơn gần nhất bên trái / bên phải\n\nint main() {\n    int n = 6;\n    stack<int> st;\n    for (int i = 0; i < n; i++) {\n        while (!st.empty() && h[st.top()] >= h[i]) st.pop();\n        Lt[i] = st.empty() ? -1 : st.top();\n        st.push(i);\n    }\n    while (!st.empty()) st.pop();\n    for (int i = n - 1; i >= 0; i--) {\n        while (!st.empty() && h[st.top()] >= h[i]) st.pop();\n        Rt[i] = st.empty() ? n : st.top();\n        st.push(i);\n    }\n    long long best = 0;\n    for (int i = 0; i < n; i++) {\n        long long s = (long long)h[i] * (Rt[i] - Lt[i] - 1);\n        if (s > best) best = s;\n    }\n    cout << best << \"\\n\";\n    return 0;\n}",viz:[{type:"bars",of:"h",ptr:["i"]},{type:"cont",of:"st"},{type:"cells",of:"Lt"},{type:"cells",of:"Rt"}],py:{code:"h = [2, 1, 5, 6, 2, 3]\nn = len(h)\nLt = [0] * n     # chỉ số cột thấp hơn gần nhất bên trái\nRt = [0] * n     # ... bên phải\nst = []\nfor i in range(n):\n    while st and h[st[-1]] >= h[i]:\n        st.pop()\n    Lt[i] = st[-1] if st else -1\n    st.append(i)\nst = []\nfor i in range(n - 1, -1, -1):\n    while st and h[st[-1]] >= h[i]:\n        st.pop()\n    Rt[i] = st[-1] if st else n\n    st.append(i)\nprint(max(h[i] * (Rt[i] - Lt[i] - 1) for i in range(n)))",viz:[{type:"bars",of:"h",ptr:["i"]},{type:"cont",of:"st",as:"stack"},{type:"cells",of:"Lt"},{type:"cells",of:"Rt"}]},cs:{code:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] h = { 2, 1, 5, 6, 2, 3 };\n        int n = h.Length;\n        int[] Lt = new int[n], Rt = new int[n];   // chỉ số cột thấp hơn gần nhất bên trái / bên phải\n        Stack<int> st = new Stack<int>();\n        for (int i = 0; i < n; i++)\n        {\n            while (st.Count > 0 && h[st.Peek()] >= h[i]) st.Pop();\n            Lt[i] = st.Count == 0 ? -1 : st.Peek();\n            st.Push(i);\n        }\n        st.Clear();\n        for (int i = n - 1; i >= 0; i--)\n        {\n            while (st.Count > 0 && h[st.Peek()] >= h[i]) st.Pop();\n            Rt[i] = st.Count == 0 ? n : st.Peek();\n            st.Push(i);\n        }\n        long best = 0;\n        for (int i = 0; i < n; i++) best = Math.Max(best, (long)h[i] * (Rt[i] - Lt[i] - 1));\n        Console.WriteLine(best);\n    }\n}",viz:[{type:"bars",of:"h",ptr:["i"]},{type:"cont",of:"st",as:"stack"},{type:"cells",of:"Lt"},{type:"cells",of:"Rt"}]}},{label:"Lỗi: so sánh ≤ thay cho < khi có số bằng nhau",input:"",code:"#include <iostream>\n#include <stack>\nusing namespace std;\n\nint a[5] = {2, 2, 3, 1, 1};\nint kq[5];\n\nint main() {\n    int n = 5;\n    stack<int> st;\n    for (int i = 0; i < n; i++) {\n        kq[i] = -1;\n        while (!st.empty() && a[st.top()] <= a[i]) {   // sai: phải là <\n            kq[st.top()] = a[i];\n            st.pop();\n        }\n        st.push(i);\n    }\n    for (int i = 0; i < n; i++) cout << kq[i] << \" \";\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"bars",of:"a",ptr:["i"]},{type:"cont",of:"st"},{type:"cells",of:"kq"}],py:{code:"a = [2, 2, 3, 1, 1]\nn = len(a)\nkq = [-1] * n\nst = []\nfor i in range(n):\n    while st and a[st[-1]] <= a[i]:    # sai: phải là <\n        kq[st.pop()] = a[i]\n    st.append(i)\nprint(*kq)",viz:[{type:"bars",of:"a",ptr:["i"]},{type:"cont",of:"st",as:"stack"},{type:"cells",of:"kq"}]},cs:{code:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] a = { 2, 2, 3, 1, 1 };\n        int n = a.Length;\n        int[] kq = new int[n];\n        Stack<int> st = new Stack<int>();\n        for (int i = 0; i < n; i++)\n        {\n            kq[i] = -1;\n            while (st.Count > 0 && a[st.Peek()] <= a[i])   // sai: phải là <\n            {\n                kq[st.Pop()] = a[i];\n            }\n            st.Push(i);\n        }\n        Console.WriteLine(string.Join(\" \", kq));\n    }\n}",viz:[{type:"bars",of:"a",ptr:["i"]},{type:"cont",of:"st",as:"stack"},{type:"cells",of:"kq"}]}}];
