makeEx2(document.getElementById("ex-l28"),sim28,[{t:"Bao lâu nữa trời ấm hơn",d:"Đầu vào: n (1 ≤ n ≤ 10^5) và nhiệt độ của n ngày liên tiếp (số nguyên 0 … 100). Đầu ra: với mỗi ngày, số ngày phải chờ tới ngày đầu tiên ấm hơn hẳn (0 nếu không có).",tests:[{in:"8\n73 74 75 71 69 72 76 73",out:"1 1 4 2 1 1 0 0"},{in:"4\n30 40 50 60",out:"1 1 1 0"},{in:"3\n30 60 90",out:"1 1 0"},{in:"1\n50",out:"0"},{in:"4\n60 50 40 30",out:"0 0 0 0"},{in:"4\n5 5 5 6",out:"3 2 1 0"},{in:"6\n1 3 2 3 1 4",out:"1 4 1 2 1 0"}],start:"#include <iostream>\n#include <stack>\nusing namespace std;\n\nint t[100000], kq[100000];\n\nint main() {\n    int n;\n    cin >> n;\n    for (int i = 0; i < n; i++) cin >> t[i];\n    // ngăn xếp chỉ số các ngày chưa tìm thấy ngày ấm hơn\n    for (int i = 0; i < n; i++) cout << kq[i] << \" \";\n    cout << \"\\n\";\n    return 0;\n}",perf:{gen:n=>n+"\n"+Array.from({length:n},(_,i)=>i==n-1?100:50-(i%40)).join(" "),ns:[500,2000,8000],need:"n",limit:n=>45*n+200,why:"Nhìn sang phải từng ngày là O(n²) khi trời lạnh dần lâu. Mỗi ngày vào, ra ngăn xếp một lần: O(n)."},py:{start:"n = int(input())\nt = list(map(int, input().split()))\nkq = [0] * n\n# ngăn xếp chỉ số các ngày chưa tìm thấy ngày ấm hơn\nprint(*kq)",hints:["Giống bài phần tử lớn hơn tiếp theo, nhưng lưu khoảng cách i − j thay vì giá trị: vì vậy ngăn xếp phải chứa CHỈ SỐ.","Ấm hơn hẳn: điều kiện pop là t[st[-1]] < t[i] (không phải ≤).","Các ngày còn lại trong ngăn xếp khi hết dãy có đáp án 0."]},cs:{start:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        int[] t = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int[] kq = new int[n];\n        // ngăn xếp chỉ số các ngày chưa tìm thấy ngày ấm hơn\n        Console.WriteLine(string.Join(\" \", kq));\n    }\n}",hints:["Giống bài phần tử lớn hơn tiếp theo, nhưng lưu khoảng cách i − j thay vì giá trị: vì vậy ngăn xếp phải chứa CHỈ SỐ.","Ấm hơn hẳn: điều kiện pop là t[st.Peek()] < t[i] (không phải ≤).","Các ngày còn lại trong ngăn xếp khi hết dãy có đáp án 0 (mảng mới tạo đã toàn 0)."]}},{t:"Chuỗi ngày giá không cao hơn",d:"Giá cổ phiếu n ngày là p₁ … pₙ. “Độ dài chuỗi” của ngày i là số ngày liên tiếp tính ngược từ ngày i (kể cả ngày i) mà giá không vượt quá pᵢ. Đầu vào: n (1 ≤ n ≤ 10^5) và dãy p (≤ 10^9). Đầu ra: độ dài chuỗi của từng ngày.",tests:[{in:"7\n100 80 60 70 60 75 85",out:"1 1 1 2 1 4 6"},{in:"1\n10",out:"1"},{in:"5\n1 2 3 4 5",out:"1 2 3 4 5"},{in:"5\n5 4 3 2 1",out:"1 1 1 1 1"},{in:"4\n3 3 3 3",out:"1 2 3 4"},{in:"5\n7 2 7 2 7",out:"1 1 3 1 5"}],start:"#include <iostream>\n#include <stack>\nusing namespace std;\n\nint p[100000];\n\nint main() {\n    int n;\n    cin >> n;\n    for (int i = 0; i < n; i++) cin >> p[i];\n    // tìm ngày gần nhất bên trái có giá LỚN HƠN p[i]\n    cout << \"\\n\";\n    return 0;\n}",perf:{gen:n=>n+"\n"+Array.from({length:n},(_,i)=>i+1).join(" "),ns:[500,2000,8000],need:"n",limit:n=>45*n+200,why:"Đếm ngược từng ngày là O(n²) khi giá tăng liên tục. Ngăn xếp đơn điệu chỉ cần O(n)."},py:{start:"n = int(input())\np = list(map(int, input().split()))\nout = []\n# tìm ngày gần nhất bên trái có giá LỚN HƠN p[i]\nprint(*out)",hints:["Chuỗi của ngày i kéo dài tới ngay sau ngày gần nhất bên trái có giá LỚN HƠN p[i]. Nếu ngày đó là j thì đáp án i − j; không có thì i + 1.","Biến thể “lớn hơn gần nhất bên trái”: pop khi p[st[-1]] ≤ p[i], rồi st[-1] còn lại là j.","Giá bằng nhau vẫn tính vào chuỗi, nên điều kiện pop là ≤."]},cs:{start:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        int[] p = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int[] kq = new int[n];\n        // tìm ngày gần nhất bên trái có giá LỚN HƠN p[i]\n        Console.WriteLine(string.Join(\" \", kq));\n    }\n}",hints:["Chuỗi của ngày i kéo dài tới ngay sau ngày gần nhất bên trái có giá LỚN HƠN p[i]. Nếu ngày đó là j thì đáp án i − j; không có thì i + 1.","Biến thể “lớn hơn gần nhất bên trái”: Pop khi p[st.Peek()] ≤ p[i], rồi đỉnh còn lại là j.","Giá bằng nhau vẫn tính vào chuỗi, nên điều kiện Pop là ≤."]}},{t:"Hình chữ nhật lớn nhất",d:"Đầu vào: n (1 ≤ n ≤ 10^5) và chiều cao h₀ … hₙ₋₁ (0 ≤ hᵢ ≤ 10^9) của các cột rộng 1 đứng sát nhau. Đầu ra: diện tích lớn nhất của một hình chữ nhật nằm trong biểu đồ (cạnh song song với các trục).",tests:[{in:"6\n2 1 5 6 2 3",out:"10"},{in:"1\n4",out:"4"},{in:"2\n2 4",out:"4"},{in:"5\n1 1 1 1 1",out:"5"},{in:"7\n6 2 5 4 5 1 6",out:"12"},{in:"2\n0 0",out:"0"},{in:"3\n1000000000 1000000000 1000000000",out:"3000000000"}],start:"#include <iostream>\n#include <stack>\nusing namespace std;\n\nlong long h[100000];\nint Lt[100000], Rt[100000];\n\nint main() {\n    int n;\n    cin >> n;\n    for (int i = 0; i < n; i++) cin >> h[i];\n    // Lt[i], Rt[i]: chỉ số cột thấp hơn gần nhất bên trái, bên phải\n    long long best = 0;\n    cout << best << \"\\n\";\n    return 0;\n}",perf:{gen:n=>n+"\n"+Array.from({length:n},(_,i)=>i+1).join(" "),ns:[500,2000,8000],need:"n",limit:n=>80*n+200,why:"Mở rộng sang hai bên cho từng cột là O(n²). Hai lượt ngăn xếp đơn điệu tìm biên trái, phải trong O(n)."},py:{start:"n = int(input())\nh = list(map(int, input().split()))\nLt = [-1] * n     # chỉ số cột thấp hơn gần nhất bên trái\nRt = [n] * n      # ... bên phải\nbest = 0\nprint(best)",hints:["Hình tốt nhất cao đúng bằng một cột i và kéo sang hai bên tới trước cột thấp hơn đầu tiên.","Lt[i]: cột thấp hơn gần nhất bên trái (−1 nếu không có); Rt[i]: bên phải (n nếu không có). Chiều rộng Rt[i] − Lt[i] − 1.","Lượt tính Rt duyệt i từ n − 1 về 0: range(n - 1, -1, -1)."]},cs:{start:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        long[] h = Array.ConvertAll(Console.ReadLine().Split(), long.Parse);\n        int[] Lt = new int[n], Rt = new int[n];   // chỉ số cột thấp hơn gần nhất bên trái, bên phải\n        long best = 0;\n        Console.WriteLine(best);\n    }\n}",hints:["Hình tốt nhất cao đúng bằng một cột i và kéo sang hai bên tới trước cột thấp hơn đầu tiên.","Lt[i]: cột thấp hơn gần nhất bên trái (−1 nếu không có); Rt[i]: bên phải (n nếu không có). Chiều rộng Rt[i] − Lt[i] − 1.","Diện tích tới 10^14: dùng long."]}}]);

makeQuiz("quiz28","score28",[{"q": "Tìm số lớn hơn tiếp theo bằng ngăn xếp: các giá trị trên ngăn xếp (đáy → đỉnh) luôn…", "o": ["tăng dần", "giảm dần (không tăng)", "bằng nhau", "lộn xộn"], "a": 1, "e": "Số nhỏ đứng sau số lớn hơn sẽ bị lấy ra ngay khi số lớn hơn xuất hiện."}, {"q": "Vòng while bên trong vòng for, nhưng tổng thời gian vẫn O(n) vì…", "o": ["while chạy tối đa 1 lần mỗi vòng for", "Mỗi chỉ số được push một lần và pop nhiều nhất một lần", "Ngăn xếp luôn rỗng", "n nhỏ"], "a": 1, "e": "Phân tích khấu hao: đếm tổng số lần pop trên cả chương trình."}, {"q": "Dãy 3 1 2. Số lớn hơn tiếp theo của từng phần tử là?", "o": ["−1 2 −1", "2 2 −1", "−1 2 3", "3 2 −1"], "a": 0, "e": "Bên phải 3 không có số lớn hơn; bên phải 1 có 2; 2 là phần tử cuối."}, {"q": "Biểu đồ cột 3 3 3. Hình chữ nhật lớn nhất có diện tích?", "o": ["3", "6", "9", "27"], "a": 2, "e": "Cao 3, rộng 3."}]);

